        questions = B.spread(listOf(
            // Identity, governance and monitoring: logging and monitoring
            B.q("sa-m4-1", "sa-monitoring", "Logs from European resources must be stored only in Europe, and logs from Australian resources only in Australia, while central operators can still query both. What workspace design do you recommend?", listOf("One workspace in West Europe for all logs, with table-level access so only approved staff read Australian rows", "A workspace in each geography, with operators granted access to both and querying across them", "A workspace in each geography, plus diagnostic settings also sending all logs to one central workspace", "One workspace in Australia East for all logs, so operators have a single place to query"), setOf(1), "Log data is stored in the region of the workspace. A workspace in each geography keeps data where the law requires, and one KQL query can still read several workspaces for operators who have access to both.",
                scenario = "Lyrebird Health runs its Android telehealth app in West Europe and Australia East. Health data laws in both places say logs that mention patients must not leave the country or region.",
                whyWrong = mapOf(
                    0 to "Table-level access controls who reads the rows, but Australian logs would still be stored in Europe.",
