            B.q("sa-m4-4", "sa-monitoring", "API traffic follows a daily and weekly pattern, so a fixed threshold either fires all night or misses daytime problems. What do you recommend?", listOf("A metric alert with a static threshold set to the daily average", "A metric alert with dynamic thresholds", "Turn off alerts at night", "A log alert that runs once a day"), setOf(1), "Dynamic thresholds learn the normal pattern of a metric, including daily and weekly cycles, and alert when the value moves outside its expected range for that time.",
                scenario = "Wildflower Foods' Android ordering app is busy at lunch and dinner and almost silent at night. Its static request-rate alert either floods the on-call phone or stays silent.",
