            // Identity
            B.q("sa-m4-5", "sa-identity", "After a merger, users in the parent tenant must appear automatically in the subsidiary's tenant, and leave it when they leave the parent, so they can use its apps. What do you recommend?", listOf("Bulk B2B invitations from a CSV export of the parent tenant's users", "Cross-tenant synchronization from the parent tenant to the subsidiary's tenant", "B2B direct connect between the two tenants in cross-tenant access settings", "Microsoft Entra Connect Sync from the parent tenant to the subsidiary's tenant"), setOf(1), "Cross-tenant synchronization automatically creates, updates and removes B2B users in another tenant of the same organisation. Leavers in the source tenant are removed in the target without manual work.",
                scenario = "Corvid Group bought Pipit Studios, which keeps its own Microsoft Entra tenant for now. Corvid's staff need Pipit's internal apps, including its Android design-review app.",
