            B.q("sa-m4-9", "sa-authorization", "Several apps, each with dev, test and production environments, store secrets. A breach of one app's vault must not expose the others. What vault design do you recommend?", listOf("One Key Vault for the whole company", "One Key Vault per app per environment", "One Key Vault per environment shared by all apps", "Store secrets in App Service settings instead"), setOf(1), "Microsoft recommends a vault per application per environment. Access is granted at the vault, so separate vaults keep each app's secrets, and each environment's, apart, and limit the damage if one is exposed.",
                scenario = "Lindenfield Software builds four Android apps, each with its own API in dev, test and production. Today all their secrets share one vault that every developer can read.",
                whyWrong = mapOf(
