            B.q("sa-m4-10", "sa-authorization", "Engineers must become members of a group that holds several Azure and Entra roles only when needed, for a few hours, with approval. What do you recommend?", listOf("Privileged Identity Management for Groups, with eligible membership", "A dynamic membership group whose rule adds engineers marked as on call", "Permanent active membership of a role-assignable group that holds the roles", "A Conditional Access policy requiring MFA and a compliant device for the group"), setOf(0), "PIM for Groups makes people eligible members or owners of a group. They activate membership for a limited time, with approval if required, and get every role that group holds while active.",
                scenario = "Aldgate Retail's on-call engineers for its Android app need a bundle of roles during incidents. Assigning each role through PIM one by one has become hard to manage.",
