            B.q("sa-m4-16", "sa-governance", "Nobody may hold both the access package that creates payments and the one that approves them. What do you recommend?", listOf("Mark the two access packages as incompatible in entitlement management", "Require manager approval in the policies of both access packages", "Run a quarterly access review of both access packages", "Add an Azure Policy deny rule that blocks holding both access packages"), setOf(0), "Entitlement management can mark access packages, or groups, as incompatible. Someone who holds one cannot request the other, which enforces separation of duties.",
                scenario = "Ridgeway Finance's back office approves refunds requested through its Android app. Auditors found one clerk able to both create and approve a refund.",
