            B.q("sa-m4-19", "sa-relational", "Every query against the database must be recorded and searchable with other logs for two years. What do you recommend?", listOf("Azure SQL auditing sending to a Log Analytics workspace", "The activity log sent to the same Log Analytics workspace", "Query Store runtime statistics sent to a Log Analytics workspace", "Microsoft Defender for SQL alerts exported to Log Analytics"), setOf(0), "Azure SQL auditing records database events, including queries, and can send them to Log Analytics, storage or Event Hubs. In a workspace they can be searched with other logs and kept as long as needed.",
                scenario = "Kingfisher Credit's regulator requires a two-year record of who queried account data behind its Android lending app.",
